from collections import defaultdict
from typing import Any

# defaultdict -> is a subclass of dict that automatically initializes a missing key with a value generated by a specified function
default: defaultdict[Any, int] = defaultdict(int)

# this is usefult when we want to count the appearing of values 

greetings = "Hello samuel vargas, how are you today?"


for char in greetings: 
    default[char] += 1 
    
    
print(dict(default))

